import {billPayment,billStatus,saveBill,payBill,removeBill,saveGoal,goalProgress,contributeGoal,removeGoal,preservePlanningLink,monthlyClosingSummary,closeMonth,closureChanged} from './planning.js?v=income-display-20261114';
import {previousMonth,copyCategoryBudgets,budgetStatus,monthlyComparison,favoriteMatches,toggleFavorite,createBackup,parseBackup} from './features.js?v=income-display-20261114';
import {money,number,parseMoney,summarize,inMonth,breakdown,dailyExpenses,csv,categoryBudgetSummary,setMonthlySalary,allocationSummary,categoryLabel,mealSummary,setMealVouchers,validateMealPayment,resetCategoryBudget,monthlyIncome,mainCategoryBalances} from './finance.js?v=income-display-20261114';
import {initialState,loadState,saveState,demoTransactions} from './storage.js?v=income-display-20261114';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}"></i>`, today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Bucharest'}).format(new Date());
let state,storageFailed=false,pendingRestore=null,budgetTab='monthly',billDay='';
try{state=loadState();}catch{state=initialState();storageFailed=true;}
let month=today().slice(0,7), page='dashboard', filter={search:'',category:'',type:''},tablePage=1,modal=null,toastTimer;
const pages={dashboard:'Dashboard',transactions:'Tranzacții',budgets:'Bugete',categories:'Categorii',reports:'Rapoarte',settings:'Setări'};
function icons(){window.lucide?.createIcons({attrs:{'aria-hidden':'true','stroke-width':1.7}});}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(next){if(storageFailed)throw Error('Datele existente nu pot fi citite. Nu le suprascriem. Verifică stocarea browserului.');try{saveState(next);}catch{throw Error('Salvarea a eșuat. Verifică spațiul disponibil și permisiunile browserului.');}state=next;}
function mutate(fn){const next=structuredClone(state);fn(next);persist(next);}
function applyAppearance(){const logo=$('#brand-logo');if(logo)logo.setAttribute('src',state.theme==='light'?'assets/ixpence-logo-light.svg?v=wordmark':'assets/ixpence-logo.svg?v=wordmark');document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('collapsed',!!state.collapsed);$('#theme').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme').setAttribute('aria-label',state.theme==='dark'?'Activează tema luminoasă':'Activează tema întunecată');const collapse=$('#collapse');collapse.setAttribute('aria-expanded',String(!state.collapsed));collapse.setAttribute('aria-label',state.collapsed?'Extinde meniul':'Restrânge meniul');}
const monthRows=()=>inMonth(state.transactions,month), budget=()=>state.budgets[month]||0;
function monthName(){return new Date(month+'-01T12:00:00').toLocaleDateString('ro-RO',{month:'long',year:'numeric'});}
function metric(title,value,ico,kind,sub,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-top"><span>${title}</span><span class="metric-icon ${kind}">${icon(ico)}</span></div><div class="metric-value">${number(value)}<span class="currency">RON</span></div>${sub?`<div class="metric-bottom">${sub}</div>`:''}</article>`;}
function metrics(){const s=summarize(monthRows(),budget()),m=mealSummary(state,month),income=monthlyIncome(state,month);if(page==='dashboard'){
 const salaries=monthRows().filter(t=>t.type==='income'&&(t.salaryMonth===month||/^salariu(?:\s|$)/i.test(t.name))),salary=salaries.length?salaries.reduce((sum,t)=>sum+t.amount,0):budget();
 return `<section class="metrics dashboard-metrics" aria-label="Rezumat financiar"><article class="metric featured dashboard-balance-card"><div class="balance-main"><h2>Sold disponibil</h2></div><dl class="income-breakdown"><div><dt>Salariu:</dt><dd class="income-amount metric-value">${number(salary)}<span class="currency">RON</span></dd></div><div><dt>Bonuri:</dt><dd class="income-amount metric-value">${number(m.received)}<span class="currency">RON</span></dd></div></dl></article></section>`;
};return `${page==='dashboard'?'':`<div class="section-caption"><span>${icon('circle-dot')} REZUMATUL LUNII</span><span>Sume în RON · ${monthRows().length} tranzacții</span></div>`}<section class="metrics ${page==='dashboard'?'dashboard-metrics':''}" aria-label="Rezumat financiar">${page==='dashboard'?'':`${metric('Sold disponibil',s.balance,'wallet','',page==='dashboard'?'':'Venituri minus plăți din bani',true)}${metric('Venituri totale',income.total,'arrow-down-left','green',page==='dashboard'?'':`Bani ${money(income.cash)} + bonuri ${money(income.vouchers)}`)}${metric('Cheltuieli totale',s.expenses,'arrow-up-right','red',`<span class="red">${icon('arrow-up-right')}</span> ${monthRows().filter(t=>t.type==='expense').length} plăți în această lună`)}`}<article class="metric"><div class="metric-top"><span>Buget rămas</span><span class="metric-icon">${icon('chart-pie')}</span></div><div class="metric-value ${budget()&&s.remaining<0?'red':''}">${budget()?number(s.remaining):'—'}<span class="currency">RON</span></div><div class="budget-progress"><div class="progress"><span style="width:${Math.min(s.used,100)}%;${s.used>100?'background:var(--red)':''}"></span></div><div><span>${budget()?Math.round(s.used)+'% utilizat':'Niciun buget stabilit'}</span><span>${budget()?'din '+number(budget())+' RON':''}</span></div></div><button class="tiny-edit" data-action="budget" aria-label="Editează bugetul lunar">${icon('pencil')}</button></article><article class="metric meal-metric"><div class="metric-top"><span>Bonuri de masă</span><span class="metric-icon green">${icon('ticket')}</span></div><div class="metric-value">${number(m.received)}<span class="currency">RON</span></div>${page==='dashboard'?'':`<div class="metric-bottom">Disponibil: ${money(m.remaining)}</div>`}<button class="tiny-edit" data-action="meal" aria-label="Adaugă sau editează bonurile de masă">${icon(m.received?'pencil':'plus')}</button></article></section>`;}
function lineChart(){const rows=monthRows(),data=dailyExpenses(rows,month),s=summarize(rows),max=Math.max(10000,...data.map(d=>d.total)),ceil=Math.ceil(max/10000)*10000;const x=i=>40+i/(data.length-1)*500,y=v=>168-v/ceil*138,points=data.map((d,i)=>`${x(i)},${y(d.total)}`).join(' ');return `<article class="panel"><div class="panel-head"><div><h2>Evoluția cheltuielilor</h2>${page==='dashboard'?'':`<p>Un ritm mai clar, zi de zi.</p>`}</div><span class="chart-legend"><i class="dot" style="background:#818cf8"></i>Cheltuieli</span></div><div class="chart-wrap"><svg class="line-chart" viewBox="0 0 560 200" role="img" aria-label="Cheltuieli zilnice în ${esc(monthName())}: ${esc(money(s.expenses))}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#818cf8" stop-opacity=".24"/><stop offset="100%" stop-color="#818cf8" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let v=ceil*i/3;return `<line class="grid" x1="40" x2="540" y1="${y(v)}" y2="${y(v)}"/><text x="30" y="${y(v)+3}" text-anchor="end">${number(v)}</text>`;}).join('')}<polygon points="40,168 ${points} 540,168" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#818cf8" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.total)}" r="5" fill="transparent"><title>${d.day} ${monthName()}: ${money(d.total)}</title></circle>`).join('')}${[1,5,10,15,20,25,data.length].map(d=>`<text x="${x(d-1)}" y="192" text-anchor="middle">${String(d).padStart(2,'0')}</text>`).join('')}</svg></div><div class="chart-summary"><span>Medie zilnică <strong>${money(Math.round(s.expenses/data.length))}</strong></span><span>Total <strong>${money(s.expenses)}</strong></span></div></article>`;}
function donutChart(){const data=breakdown(monthRows(),state.categories),total=data.reduce((s,c)=>s+c.total,0);let offset=0;return `<article class="panel"><div class="panel-head"><div><h2>Unde se duc banii</h2>${page==='dashboard'?'':`<p>Cheltuielile tale, pe categorii.</p>`}</div><span class="chart-legend">RON</span></div><div class="donut-layout"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="Distribuția cheltuielilor pe categorii"><circle cx="60" cy="60" r="49" fill="none" stroke="var(--line)" stroke-width="11"/>${data.map(c=>{const part=c.total/total*307.876;const result=`<circle cx="60" cy="60" r="49" fill="none" stroke="${c.color}" stroke-width="11" stroke-dasharray="${Math.max(0,part-2)} ${307.876-Math.max(0,part-2)}" stroke-dashoffset="${-offset}"><title>${esc(c.name)}: ${money(c.total)} (${(c.total/total*100).toFixed(1)}%)</title></circle>`;offset+=part;return result;}).join('')}</svg><div class="donut-center"><span>Total cheltuieli</span><strong>${number(total)}</strong><small>RON</small></div></div><div class="category-legend">${data.length?data.map(c=>`<div class="legend-row"><i class="dot" style="background:${c.color}"></i><div>${esc(c.name)}<small>${money(c.total)}</small></div><strong>${Math.round(c.total/total*100)}%</strong></div>`).join(''):page==='dashboard'?'':`<div class="empty-chart">Fiecare leu contează.<br>Adaugă o cheltuială pentru a vedea distribuția.</div>`}</div></div></article>`;}
function charts(){return `<section class="charts" aria-label="Grafice financiare">${lineChart()}${donutChart()}</section>`;}
function filtered(){const q=filter.search.toLocaleLowerCase('ro-RO');return monthRows().filter(t=>(!filter.category||t.category===filter.category||state.categories.find(c=>c.id===t.category)?.parentId===filter.category)&&(!filter.type||t.type===filter.type)&&(!q||(t.name+' '+(t.description||'')).toLocaleLowerCase('ro-RO').includes(q))).sort((a,b)=>b.date.localeCompare(a.date));}
function transactionRows(){const rows=filtered(),limit=page==='dashboard'?5:10,totalPages=Math.max(1,Math.ceil(rows.length/limit));tablePage=Math.min(tablePage,totalPages);const visible=rows.slice((tablePage-1)*limit,tablePage*limit);return `<div class="table-scroll"><table><thead><tr><th>Denumire</th><th>Categorie</th><th>Dată</th><th>Tip</th><th style="text-align:right">Sumă</th><th aria-label="Acțiuni"></th></tr></thead><tbody>${visible.map(t=>{const c=state.categories.find(c=>c.id===t.category);return `<tr><td><div class="transaction-name"><span class="tile" style="color:${c?.color||'#818cf8'}">${icon(t.type==='income'?'arrow-down-left':c?.icon||'receipt-text')}</span>${esc(t.name)}${t.paymentSource==='meal'?'<span class="tag meal-tag">Bonuri</span>':''}${t.billId?'<span class="tag planning-tag">Factură</span>':t.goalId?'<span class="tag planning-tag">Obiectiv</span>':''}</div></td><td><span class="tag" style="--tag:${c?.color||'#94a3b8'}">${esc(categoryLabel(c,state.categories))}</span></td><td>${new Date(t.date+'T12:00:00').toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'})}</td><td><span class="type-tag ${t.type==='income'?'green':'muted'}"><i></i>${t.type==='income'?'Venit':'Cheltuială'}</span></td><td class="amount ${t.type==='income'?'income':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td><td class="row-actions"><button class="icon-button favorite-star ${(state.favorites||[]).some(f=>favoriteMatches(f,t))?'is-favorite':''}" data-favorite="${t.id}" aria-label="${(state.favorites||[]).some(f=>favoriteMatches(f,t))?'Elimină din':'Salvează la'} favorite · ${esc(t.name)}" title="Salvează sau elimină modelul favorit">${icon('star')}</button><button class="icon-button" data-edit="${t.id}" aria-label="Editează ${esc(t.name)}">${icon('pencil')}</button><button class="icon-button" data-delete="${t.id}" aria-label="Șterge ${esc(t.name)}">${icon('trash-2')}</button></td></tr>`;}).join('')}</tbody></table></div>${!visible.length&&monthRows().length?`<div class="empty-state"><h3>Nicio tranzacție găsită</h3><p>Încearcă altă căutare sau modifică filtrele.</p><button class="button" data-action="reset-filters">Resetează filtrele</button></div>`:''}<div class="table-footer"><span>${rows.length?`${(tablePage-1)*limit+1}–${Math.min(tablePage*limit,rows.length)} din ${rows.length}`:'0'} tranzacții</span><div class="pagination"><span>Pagina ${tablePage} din ${totalPages}</span><button class="icon-button" data-action="table-prev" aria-label="Pagina anterioară" ${tablePage===1?'disabled':''}>${icon('chevron-left')}</button><button class="icon-button" data-action="table-next" aria-label="Pagina următoare" ${tablePage===totalPages?'disabled':''}>${icon('chevron-right')}</button></div></div>`;}
function transactions(){return `${page==='dashboard'?'':favoritesView()}<section class="panel transactions-panel"><div class="panel-head"><div><h2>${page==='dashboard'?'Tranzacții recente':'Toate tranzacțiile'}</h2>${page==='dashboard'?'':'<p>Micile detalii care fac imaginea de ansamblu.</p>'}</div><div class="table-head-actions"><button class="button primary" data-action="add">${icon('plus')}Adaugă tranzacție</button>${page==='dashboard'?`<a href="#transactions" class="text-button">Vezi toate ${icon('arrow-up-right')}</a>`:''}</div></div><div class="filters"><div class="search">${icon('search')}<input id="search" type="search" placeholder="Caută o tranzacție..." aria-label="Caută tranzacții" value="${esc(filter.search)}"></div><select id="category-filter" aria-label="Filtrează după categorie"><option value="">Toate categoriile</option>${state.categories.map(c=>`<option value="${c.id}" ${filter.category===c.id?'selected':''}>${esc(categoryLabel(c,state.categories))}</option>`).join('')}</select><select id="type-filter" aria-label="Filtrează după tip"><option value="">Toate tipurile</option><option value="income" ${filter.type==='income'?'selected':''}>Venituri</option><option value="expense" ${filter.type==='expense'?'selected':''}>Cheltuieli</option></select><button class="button" data-action="export">${icon('download')}<span>Export CSV</span></button></div><div id="table-area">${transactionRows()}</div></section>`;}
function monthlyBudgetView(){const s=summarize(monthRows(),budget());return `<div class="section-toolbar"><span>Buget lunar · ${esc(monthName())}</span><div class="toolbar-buttons"><button class="button" data-action="copy-budgets">${icon('copy')}Copiază luna trecută</button><button class="button primary" data-action="budget">${icon('pencil')}Editează bugetul</button></div></div><section class="panel budget-card"><div class="section-body"><span class="eyebrow">BUGET ALOCAT</span><div class="large-value">${money(budget())}</div><div class="progress"><span style="width:${Math.min(s.used,100)}%;${s.used>100?'background:var(--red)':''}"></span></div><div class="budget-details"><span>${money(s.income-s.balance)} cheltuiți din bani</span><span>${budget()?Math.round(s.used)+'% utilizat':'Neconfigurat'}</span></div><h3>${!budget()?'O lună bună începe cu un plan.':s.remaining<0?'Ai depășit bugetul lunar.':'Mai ai '+money(s.remaining)+' la dispoziție.'}</h3><p>Bugetul este limita ta de cheltuieli pentru luna selectată. Îl poți modifica oricând, iar tranzacțiile tale vor rămâne salvate.</p><button class="button" data-action="budget">${icon('wallet')}${budget()?'Modifică bugetul':'Configurează bugetul'}</button> <a class="button" href="#categories">${icon('shapes')}Bugete pe categorii</a></div></section>`;}
function adjustCategoryAllocation(state,month,id,delta){
 const budgets=state.categoryBudgets??={};
 const allocations=budgets[month]??={};
 const amount=Math.max(0,(allocations[id]||0)+delta);
 if(!Number.isSafeInteger(amount))throw Error('Suma este prea mare.');
 if(amount)allocations[id]=amount;else delete allocations[id];
}
function categoriesView(){
const categories=categoryBudgetSummary(state.transactions,state.categories,state.categoryBudgets,month,mealSummary(state,month).allocated),plan=allocationSummary(state.categories,state.categoryBudgets,month,budget());
const categoryActions=c=>`<button class="icon-button" data-reset-budget="${c.id}" title="Resetează bugetul" aria-label="Resetează bugetul · ${esc(c.name)}">${icon('rotate-ccw')}</button>${c.legacy?'':`<button class="icon-button" data-edit-category="${c.id}" title="Editează numele" aria-label="Editează numele · ${esc(c.name)}">${icon('pencil')}</button><button class="icon-button" data-add-child="${c.parentId||c.id}" title="Adaugă subcategorie" aria-label="Adaugă subcategorie · ${esc(c.name)}">${icon('plus')}</button><button class="icon-button" data-delete-category="${c.id}" title="Șterge" aria-label="Șterge · ${esc(c.name)}">${icon('trash-2')}</button>`}`;
const allocationControls=c=>`<div class="allocation-adjust"><div class="allocation-stepper"><button class="icon-button" data-allocation-step="-1" data-allocation-id="${c.id}" aria-label="Scade 1 RON din ${esc(c.name)}" ${(state.categoryBudgets?.[month]?.[c.id]||0)===0?'disabled':''}>${icon('minus')}</button><strong>${money(c.allocated)}</strong><button class="icon-button" data-allocation-step="1" data-allocation-id="${c.id}" aria-label="Adaugă 1 RON la ${esc(c.name)}">${icon('plus')}</button></div><button class="text-button" data-allocation-more="${c.id}">Adaugă mai mult</button></div>`;
const card=c=>`<article class="panel category-budget-card budget-watch-${budgetStatus(c.allocated,c.spent).level}" style="--tag:${c.color}"><div class="category-card"><span class="tile">${icon(c.icon)}</span><div><h3>${esc(c.name)}</h3><p>${c.parentId?'Subcategorie · '+esc(state.categories.find(parent=>parent.id===c.parentId)?.name||''):c.custom?'Categorie personalizată':'Categorie implicită'}</p></div><div class="row-actions category-controls">${categoryActions(c)}</div></div><div class="category-budget-body">${budgetBadge(c.allocated,c.spent)}${c.id==='cat-0'?`<p class="meal-detail">Bani: ${money(state.categoryBudgets?.[month]?.['cat-0']||0)} · Bonuri: ${money(mealSummary(state,month).allocated)}</p>`:''}<div class="category-allocation"><span>${c.id==='cat-4'?'Planificat pentru plată':'Buget alocat'}</span>${allocationControls(c)}</div><div class="progress"><span style="width:${Math.min(c.used,100)}%;background:${c.used>=100?'var(--red)':c.used>=80?'#fbbf24':c.color}"></span></div><div class="category-budget-details"><span>${c.id==='cat-4'?'Achitat':'Cheltuit'}<strong>${money(c.spent)}</strong></span><span>${c.remaining!==null&&c.remaining<0?'Depășire':c.id==='cat-4'?'Rămas de plată':'Rămas'}<strong class="${c.remaining!==null&&c.remaining<0?'red':''}">${c.remaining===null?'—':money(Math.abs(c.remaining))}</strong></span></div><button class="button" data-category-budget="${c.id}">${icon(c.allocated?'pencil':'plus')}${c.allocated?'Editează bugetul':'Setează bugetul'}</button></div></article>`;
return `<section class="allocation-overview panel" aria-label="Repartizarea bugetului lunar"><div class="allocation-heading"><div><span class="eyebrow">BUGETUL TĂU · ${esc(monthName().toLocaleUpperCase('ro-RO'))}</span><h2>Fiecare leu are un loc.</h2></div><button class="button" data-action="salary">${icon('wallet')}${budget()?'Editează bugetul total':'Adaugă buget'}</button></div><div class="allocation-values"><div><span>Buget total (salariu)</span><strong>${money(plan.total)}</strong></div><div><span>Alocat pe categorii</span><strong>${money(plan.allocated)}</strong></div><div class="allocation-remaining"><span>${plan.unallocated<0?'Alocat peste buget':'Rămas de repartizat'}</span><strong class="${plan.unallocated<0?'red':'purple'}">${money(Math.abs(plan.unallocated))}</strong></div></div><div class="progress"><span style="width:${plan.total?Math.min(plan.allocated*100/plan.total,100):0}%;${plan.unallocated<0?'background:var(--red)':''}"></span></div><p>${plan.unallocated<0?'Alocările depășesc bugetul total. Poți ajusta sumele din categorii.':'Suma rămasă scade când aloci bani unei categorii și crește când reduci sau elimini o alocare.'} Cheltuielile se urmăresc separat în fiecare categorie. Bonurile de masă nu se scad din salariu.</p><p class="meal-detail">Bonuri de masă: ${money(mealSummary(state,month).received)} · Alocate exclusiv Alimentație: ${money(mealSummary(state,month).allocated)} · De alocat doar la Alimentație: ${money(mealSummary(state,month).unallocated)}</p></section><div class="section-toolbar"><span>${categories.filter(c=>!c.isGroup&&!c.parentId).length+categories.filter(c=>c.isGroup).length} categorii · ${esc(monthName())}</span><div class="toolbar-buttons"><button class="button" data-action="copy-budgets">${icon('copy')}Copiază luna trecută</button><button class="button primary" data-action="add-category">${icon('plus')}Adaugă categorie</button></div></div><section class="category-grid">${categories.filter(c=>!c.parentId).sort((a,b)=>{const order=['cat-car','cat-6','cat-7','cat-2','cat-3','cat-misc','cat-4'];return (order.includes(a.id)?order.indexOf(a.id):99)-(order.includes(b.id)?order.indexOf(b.id):99);}).map(c=>c.isGroup?`<section class="category-group panel budget-watch-${budgetStatus(c.allocated,c.spent).level}"><div class="category-group-heading"><div><h2>${icon(c.icon)} ${esc(c.name)}</h2><p>Totalul include alocările subcategoriilor și eventualele alocări anterioare.</p>${budgetBadge(c.allocated,c.spent)}</div><div><div><span>Total alocat</span>${allocationControls(c)}</div><span>Cheltuit <strong>${money(c.spent)}</strong></span><div class="category-controls">${categoryActions(c)}</div></div></div><div class="category-grid">${categories.filter(child=>child.parentId===c.id).map(card).join('')}${((state.categoryBudgets?.[month]?.[c.id]||0)||monthRows().some(t=>t.type==='expense'&&t.category===c.id))?card({...c,isGroup:false,legacy:true,custom:false,name:'Alocare anterioară · '+c.name,allocated:state.categoryBudgets?.[month]?.[c.id]||0,...(()=>{const allocated=state.categoryBudgets?.[month]?.[c.id]||0,spent=monthRows().filter(t=>t.type==='expense'&&t.category===c.id).reduce((sum,t)=>sum+t.amount,0);return {spent,remaining:allocated?allocated-spent:null,used:allocated?spent*100/allocated:0};})()}):''}</div></section>`:card(c)).join('')}</section>`;
}

function reportsView(){const s=summarize(monthRows(),budget()),expenses=monthRows().filter(t=>t.type==='expense'),largest=expenses.reduce((a,b)=>a.amount>b.amount?a:b,{amount:0,name:'—'});return `${metrics()}${closingView()}${comparisonView()}${charts()}<section class="panel"><div class="section-body"><h3>Dincolo de cifre</h3><div class="report-stat"><span>Rată de economisire</span><strong>${s.income?((s.balance/s.income)*100).toLocaleString('ro-RO',{maximumFractionDigits:1})+'%':'—'}</strong></div><div class="report-stat"><span>Cea mai mare cheltuială</span><strong>${esc(largest.name)}${largest.amount?' · '+money(largest.amount):''}</strong></div><div class="report-stat"><span>Valoare medie / cheltuială</span><strong>${money(expenses.length?Math.round(s.expenses/expenses.length):0)}</strong></div><p>Rata de economisire = (venituri în bani − cheltuieli din bani) / venituri în bani. Bonurile de masă sunt urmărite separat. În această versiune, sumele din categoria Economii sunt tratate ca ieșiri din buget.</p><button class="button" data-action="report-export">${icon('download')}Exportă luna în CSV</button></div></section>`;}
function settingsView(){return `<div class="settings-grid"><section class="panel section-body settings-row"><div><h3>Backup și restaurare</h3><p>Salvează toate tranzacțiile, categoriile, bugetele, bonurile, favoritele, facturile, obiectivele, închiderile de lună și setările într-un fișier JSON. Îl poți restaura în alt browser. Fișierul conține datele tale financiare; păstrează-l într-un loc sigur.</p></div><div class="toolbar-buttons"><button class="button primary" data-action="backup">${icon('download')}Descarcă backup</button><button class="button" data-action="restore">${icon('upload')}Restaurează backup</button></div></section><section class="panel section-body settings-row"><div><h3>Aspectul aplicației</h3><p>Alege tema în care te simți cel mai bine.</p></div><button class="button" data-action="theme">${icon(state.theme==='dark'?'sun':'moon')}${state.theme==='dark'?'Activează Light Mode':'Activează Dark Mode'}</button></section><section class="panel section-body settings-row"><div><h3>Datele tale rămân ale tale</h3><p>Tranzacțiile sunt salvate în acest browser, pe acest dispozitiv. Ștergerea datelor browserului le elimină. Salvează periodic un backup JSON complet sau exportă tranzacțiile în CSV.</p></div><button class="button" data-action="export-all">${icon('download')}Exportă toate datele</button></section><section class="panel section-body settings-row"><div><h3>Explorează IXpence</h3><p>Adaugă un set demonstrativ în luna selectată. Disponibil numai când nu există tranzacții salvate.</p></div><button class="button" data-action="demo" ${state.transactions.length?'disabled':''}>${icon('sparkles')}Date demo</button></section><section class="panel section-body"><h3>IXpence Expense Manager</h3><p>Versiunea 1.0 · Monedă: RON · Format: România<br>Fără autentificare, sincronizare cloud sau integrare bancară.</p></section></div>`;}
function mealCard(){const m=mealSummary(state,month);return `<section class="panel salary-planning meal-panel"><div><span class="eyebrow">${icon('ticket')} BONURI DE MASĂ · ${esc(monthName().toLocaleUpperCase('ro-RO'))}</span><h2>${money(m.remaining)} <span class="muted">disponibili în bonuri</span></h2><p>Primite: <strong>${money(m.received)}</strong> · Folosite: <strong>${money(m.spent)}</strong> · Alocate la Alimentație: <strong>${money(m.allocated)}</strong></p></div><div class="salary-actions"><button class="button primary" data-action="meal">${icon(m.received?'pencil':'plus')}${m.received?'Editează bonurile':'Adaugă bonuri de masă'}</button><a class="button" href="#categories">Vezi alocarea</a></div></section>`;}
function salaryPlanning(){
const linked=state.transactions.find(t=>t.salaryMonth===month),allocated=Object.values(state.categoryBudgets?.[month]||{}).reduce((sum,n)=>sum+n,0),unallocated=budget()-allocated;
return `<section class="panel salary-planning"><div><span class="eyebrow">PLANUL TĂU PENTRU ${esc(monthName().toLocaleUpperCase('ro-RO'))}</span><h2>${linked?'Salariul tău, împărțit cu sens.':'Începe luna cu salariul primit.'}</h2>${linked?`<p>Buget lunar: <strong>${money(budget())}</strong> · Alocat pe categorii: <strong>${money(allocated)}</strong> · <span class="${unallocated<0?'red':''}">${unallocated<0?'Alocat în plus':'De repartizat'}: <strong>${money(Math.abs(unallocated))}</strong></span></p>`:''}</div><div class="salary-actions"><button class="button primary" data-action="salary">${icon(linked?'pencil':'plus')}${linked?'Editează bugetul':'Adaugă buget'}</button><a class="button" href="#categories">${icon('shapes')}Împarte pe categorii</a></div></section>`;
}
function render(){$('#page-title').textContent=pages[page];$('#month-name').textContent=new Date(month+'-01T12:00:00').toLocaleDateString('ro-RO',{month:'long'}).toLocaleUpperCase('ro-RO');$('#month-year').textContent=month.slice(0,4);$('#prev-month').disabled=month==='1900-01';$('#next-month').disabled=month==='9999-12';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);a.dataset.page===page?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');a.title=pages[a.dataset.page];});applyAppearance();$('#content').innerHTML=page==='dashboard'?`${metrics()}${transactions()}${dashboardCategoryBars()}`:page==='transactions'?transactions():page==='budgets'?budgetView():page==='categories'?categoriesView():page==='reports'?reportsView():settingsView();icons();}
function renderTable(){$('#table-area').innerHTML=transactionRows();icons();}
function openModal(type,id){modal={type,id};$('#save').disabled=false;$('#form-error').textContent='';$('#save').className='button primary';$('#save').textContent='Salvează';const t=state.transactions.find(t=>t.id===id),c=state.categories.find(c=>c.id===id);const label=(name,html)=>`<label>${name}${html}</label>`;if(type==='transaction'){$('#dialog-title').textContent=t?'Editează tranzacția':'Adaugă tranzacție';$('#form-fields').innerHTML=`<div class="type-switch"><label><input type="radio" name="type" value="expense" ${!t||t.type==='expense'?'checked':''}><span>${icon('arrow-up-right')}Cheltuială</span></label><label><input type="radio" name="type" value="income" ${t?.type==='income'?'checked':''}><span>${icon('arrow-down-left')}Venit</span></label></div>${label('Denumire',`<input name="name" required maxlength="100" placeholder="Ex. Cumpărături săptămânale" value="${esc(t?.name||'')}">`)}<div class="field-pair">${label('Sumă (RON)',`<input name="amount" inputmode="decimal" required placeholder="0,00" value="${t?(t.amount/100).toFixed(2).replace('.',','):''}">`)}${label('Dată',`<input name="date" type="date" required value="${t?.date||(today().startsWith(month)?today():month+'-01')}">`)}</div>${label('Categorie',`<select name="category" required>${state.categories.filter(c=>!c.isGroup||t?.category===c.id).map(c=>`<option value="${c.id}" ${t?.category===c.id?'selected':''}>${esc(categoryLabel(c,state.categories))}${c.isGroup?' (categorie anterioară)':''}</option>`).join('')}<option value="uncategorized" ${t&&!state.categories.some(c=>c.id===t.category)?'selected':''}>Fără categorie</option></select>`)}${label('Plătești din',`<select name="paymentSource"><option value="cash">Bani (numerar / card)</option><option value="meal" ${t?.paymentSource==='meal'?'selected':''}>Bonuri de masă · numai Alimentație</option></select><span style="font-size:10px">Pentru o plată mixtă, introdu separat partea din bani și partea din bonuri.</span>`)}<label class="check-row"><input type="checkbox" name="saveFavorite">Salvează și ca tranzacție favorită</label>${label('Descriere (opțional)',`<textarea name="description" maxlength="500" placeholder="Un detaliu de care vrei să-ți amintești...">${esc(t?.description||'')}</textarea>`)}`;}
else if(type==='salary'){
const linked=state.transactions.find(t=>t.salaryMonth===month),incomes=monthRows().filter(t=>t.type==='income'),suggested=linked||incomes.find(t=>/^salariu(?:\s|$)/i.test(t.name));
$('#dialog-title').textContent=linked?'Editează bugetul din salariu':'Adaugă buget din salariu';
$('#form-fields').innerHTML=`<p class="delete-copy">${esc(monthName())} · Introdu salariul primit. Suma se salvează ca <strong>venit</strong> și <strong>buget lunar</strong>. Apoi o împarți în Categorii. Alocările existente se păstrează.</p>${!linked&&incomes.length?label('Tranzacția de venit',`<select name="incomeId"><option value="">Adaugă un venit nou: Salariu</option>${incomes.map(t=>`<option value="${t.id}" ${suggested?.id===t.id?'selected':''}>${esc(t.name)} · ${money(t.amount)}</option>`).join('')}</select><span style="font-size:10px">Dacă ai introdus deja salariul în Tranzacții, selectează-l pentru a evita dublarea.</span>`):`<input type="hidden" name="incomeId" value="${linked?.id||''}">`}<div class="field-pair">${label('Salariu primit (RON)',`<input name="amount" inputmode="decimal" required placeholder="Introdu suma" value="${suggested?(suggested.amount/100).toFixed(2).replace('.',','):''}">`)}${label('Data încasării',`<input name="date" type="date" required min="${month}-01" max="${month}-${new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate()}" value="${suggested?.date||(today().startsWith(month)?today():month+'-01')}">`)}</div><span class="muted" style="font-size:10px">Editarea actualizează același venit. Bugetele din alte luni rămân neschimbate.</span>`;
}
else if(type==='meal'){$('#dialog-title').textContent='Bonuri de masă';const m=mealSummary(state,month);$('#form-fields').innerHTML=`<p class="delete-copy">${esc(monthName())} · Introdu <strong>totalul bonurilor primite în această lună</strong>. Dacă ai mai multe alimentări, introdu suma lor totală. Diferența adăugată este alocată automat numai la Alimentație.</p>${label('Total lunar bonuri (RON)',`<input name="amount" inputmode="decimal" required placeholder="Introdu valoarea" value="${m.received?(m.received/100).toFixed(2).replace('.',','):''}">`)}<span class="muted" style="font-size:10px">Nu modifică salariul. Pentru o plată cu bonuri, alege sursa „Bonuri de masă” în tranzacția de alimentație.</span>`;}
else if(type==='bill'){
const b=state.bills?.find(b=>b.id===id);$('#dialog-title').textContent=b?'Editează factura':'Adaugă factură';$('#form-fields').innerHTML=`${label('Denumire',`<input name="name" required maxlength="100" value="${esc(b?.name||'')}" placeholder="Ex. Energie electrică">`)}<div class="field-pair">${label('Sumă de plată (RON)',`<input name="amount" required inputmode="decimal" value="${b?(b.amount/100).toFixed(2).replace('.',','):''}">`)}${label('Data scadentă',`<input name="dueDate" required type="date" value="${b?.dueDate||defaultDate()}">`)}</div>${label('Categoria plății',categorySelect(b?.category))}<p class="delete-copy">Factura planificată nu scade soldul. Cheltuiala se înregistrează când o marchezi ca achitată.</p>`;
}
else if(type==='bill-pay'){
const b=state.bills.find(b=>b.id===id);$('#dialog-title').textContent='Achită factura · '+b.name;$('#form-fields').innerHTML=`<p class="delete-copy">De plată: <strong>${money(b.amount)}</strong>. Alege o plată nouă sau o cheltuială deja introdusă. Nu se dublează sumele.</p>${label('Înregistrarea plății',planningSourceSelect())}${label('Data plății noi',`<input name="date" type="date" required value="${today()}">`)}<p class="muted" style="font-size:10px">Dacă asociezi o tranzacție existentă, se păstrează suma și data ei. Sunt disponibile doar cheltuieli din bani, fără altă asociere.</p>`;$('#save').textContent='Marchează ca achitată';
}
else if(type==='bill-delete'){$('#dialog-title').textContent='Ștergi factura?';$('#form-fields').innerHTML='<p class="delete-copy">Factura dispare din calendar. O eventuală plată deja înregistrată rămâne în Tranzacții.</p>';$('#save').textContent='Șterge factura';$('#save').className='button danger';}
else if(type==='goal'){
const g=state.goals?.find(g=>g.id===id);$('#dialog-title').textContent=g?'Editează obiectivul':'Obiectiv nou';$('#form-fields').innerHTML=`${label('Numele obiectivului',`<input name="name" required maxlength="100" value="${esc(g?.name||'')}" placeholder="Ex. Avans apartament">`)}<div class="field-pair">${label('Ținta (RON)',`<input name="amount" inputmode="decimal" required value="${g?(g.targetAmount/100).toFixed(2).replace('.',','):''}">`)}${label('Termen (opțional)',`<input name="deadline" type="date" value="${g?.deadline||''}">`)}</div>${label('Categoria contribuțiilor',categorySelect(g?.category))}<p class="delete-copy">Progresul adună contribuțiile asociate acestui obiectiv din toate lunile. Nu include automat orice cheltuială din categorie.</p>`;
}
else if(type==='goal-contribute'){
const g=state.goals.find(g=>g.id===id);$('#dialog-title').textContent='Pune deoparte · '+g.name;$('#form-fields').innerHTML=`${label('Contribuție nouă sau existentă',planningSourceSelect())}<div class="field-pair">${label('Sumă nouă (RON)','<input name="amount" inputmode="decimal" required>')}${label('Data contribuției noi',`<input name="date" type="date" required value="${defaultDate()}">`)}</div><p class="delete-copy">O contribuție nouă se înregistrează ca ieșire din bani. Dacă ai înregistrat deja suma în Tranzacții, asociaz-o aici pentru a nu o dubla. Pentru corecții, editează sau șterge tranzacția asociată.</p>`;$('#save').textContent='Salvează contribuția';
}
else if(type==='goal-delete'){$('#dialog-title').textContent='Ștergi obiectivul?';$('#form-fields').innerHTML='<p class="delete-copy">Obiectivul și asocierile dispar. Tranzacțiile contribuțiilor rămân în evidența cheltuielilor.</p>';$('#save').textContent='Șterge obiectivul';$('#save').className='button danger';}
else if(type==='close-month'){$('#dialog-title').textContent=state.monthClosures?.[month]?'Recalculează închiderea':'Închide luna';$('#form-fields').innerHTML=`<p class="delete-copy">Salvezi un rezumat pentru <strong>${esc(monthName())}</strong>. Nu sunt create tranzacții și nu se reportează automat soldul.</p>${closingTotals(monthlyClosingSummary(state,month))}<p class="delete-copy">Poți continua să editezi datele. Dacă valorile se schimbă, rezumatul salvat este păstrat și vei putea să-l recalculezi.</p>`;$('#save').textContent='Salvează rezumatul';}
else if(type==='reopen-month'){$('#dialog-title').textContent='Redeschide luna';$('#form-fields').innerHTML='<p class="delete-copy">Se elimină doar rezumatul salvat. Tranzacțiile, obiectivele și bugetele rămân neschimbate.</p>';$('#save').textContent='Redeschide luna';}
else if(type==='copy-budgets'){
const from=previousMonth(month),valid=new Set(state.categories.map(c=>c.id)),entries=Object.entries(state.categoryBudgets?.[from]||{}).filter(([id,n])=>valid.has(id)&&n>0);
$('#dialog-title').textContent='Copiază bugetele lunii trecute';$('#form-fields').innerHTML=`<p class="delete-copy">Din <strong>${esc(formatMonth(from))}</strong> în <strong>${esc(monthName())}</strong>: ${entries.length} alocări, în total ${money(entries.reduce((sum,[,n])=>sum+n,0))}.</p><p class="delete-copy">Se copiază doar alocările din bani pentru categoriile existente. Salariul, tranzacțiile și bonurile de masă se introduc separat în luna nouă.</p><label class="check-row"><input type="checkbox" name="replace">Înlocuiește și alocările existente din luna selectată</label><p class="muted" style="font-size:10px">Implicit se completează doar categoriile fără alocare. Bugetele din alte luni rămân neschimbate.</p>`;$('#save').textContent='Copiază bugetele';$('#save').disabled=!entries.length;
}
else if(type==='restore'){
$('#dialog-title').textContent='Restaurează backupul';const d=pendingRestore;
$('#form-fields').innerHTML=`<p class="delete-copy">Fișier valid: <strong>${d.transactions.length} tranzacții</strong>, ${d.categories.length} categorii și ${(d.favorites||[]).length} favorite, ${(d.bills||[]).length} facturi și ${(d.goals||[]).length} obiective, din ${Object.keys(d.budgets).length} luni cu buget general.</p><p class="delete-copy">Restaurarea <strong>înlocuiește toate datele din acest browser</strong>; nu adaugă și nu dublează tranzacții. Înainte de înlocuire se descarcă automat un backup al datelor curente.</p><label class="check-row"><input type="checkbox" name="confirm" required>Confirm înlocuirea datelor curente cu cele din backup</label>`;$('#save').textContent='Restaurează datele';
}
else if(type==='budget'){$('#dialog-title').textContent='Bugetul lunii';$('#form-fields').innerHTML=`<p class="delete-copy">Alege cât vrei să aloci pentru ${esc(monthName())}. Poți reveni oricând asupra sumei.</p>${label('Buget lunar (RON)',`<input name="amount" inputmode="decimal" required value="${(budget()/100).toFixed(2).replace('.',',')}">`)}<span class="muted" style="font-size:10px">Valoarea 0 dezactivează bugetul pentru această lună.</span>`;}
else if(type==='allocation-more'){$('#dialog-title').textContent='Adaugă la buget · '+c.name;$('#form-fields').innerHTML=label('Sumă de adăugat (RON)','<input name="amount" inputmode="decimal" required>');}
else if(type==='category-budget'){$('#dialog-title').textContent='Buget · '+c.name;const amount=state.categoryBudgets?.[month]?.[id]||0;$('#form-fields').innerHTML=`<p class="delete-copy">${esc(monthName())} · Introdu suma pe care o aloci pentru <strong>${esc(c.name)}</strong>. ${c.id==='cat-4'?'Pentru datorii, aceasta este suma pe care intenționezi să o achiți în luna selectată. Înregistrează plățile ca tranzacții de cheltuială în această categorie.':''}</p>${label('Sumă alocată din bani (RON)',`<input name="amount" inputmode="decimal" required placeholder="Introdu suma" value="${amount?(amount/100).toFixed(2).replace('.',','):id==='cat-0'?'0,00':''}">`)}${id==='cat-0'?label('Bonuri alocate la Alimentație (RON)',`<input name="mealAmount" inputmode="decimal" required value="${(mealSummary(state,month).allocated/100).toFixed(2).replace('.',',')}"><span style="font-size:10px">Maximum ${money(mealSummary(state,month).received)}, separat de salariu.</span>`):''}<span class="muted" style="font-size:10px">0 elimină bugetul categoriei pentru această lună. Tranzacțiile rămân salvate. Bugetul general nu se modifică automat.</span>`;}
else if(type==='subcategory'){$('#dialog-title').textContent='Subcategorie nouă · '+c.name;$('#form-fields').innerHTML=label('Numele subcategoriei','<input name="name" required maxlength="40">');}
else if(type==='category'){$('#dialog-title').textContent=c?'Redenumește categoria':'O categorie nouă';$('#form-fields').innerHTML=label('Numele categoriei',`<input name="name" required maxlength="40" value="${esc(c?.name||'')}" placeholder="Ex. Animale de companie">`);}
else if(type==='delete-category'){$('#dialog-title').textContent='Ștergi categoria?';const count=state.transactions.filter(t=>t.category===id).length;$('#form-fields').innerHTML=`<p class="delete-copy">Categoria <strong>${esc(c.name)}</strong> și bugetele ei din toate lunile vor fi șterse. ${c.isGroup?'Subcategoriile vor deveni categorii principale.':''} ${count?`${count} tranzacții vor fi păstrate fără categorie.`:'Tranzacțiile tale nu vor fi afectate.'}</p>`;$('#save').textContent='Șterge categoria';$('#save').className='button danger';}
else if(type==='delete'){$('#dialog-title').textContent='Ștergi tranzacția?';$('#form-fields').innerHTML=`<p class="delete-copy"><strong>${esc(t.name)}</strong> · ${money(t.amount)}<br>Tranzacția va fi eliminată, iar totalurile vor fi recalculate. ${t.billId?'Factura asociată va reveni la starea neachitată.':''} ${t.goalId?'Progresul obiectivului va scădea cu această sumă.':''} ${t.salaryMonth?'Fiind salariul asociat bugetului, se elimină și bugetul general al lunii. Alocările pe categorii se păstrează.':''} Această acțiune nu poate fi anulată.</p>`;$('#save').textContent='Șterge tranzacția';$('#save').className='button danger';}
icons();$('#dialog').showModal();requestAnimationFrame(()=>$('#form-fields input[name="name"],#form-fields input[name="amount"],#save')?.focus());}
$('#form').addEventListener('change',e=>{if(['goal-contribute','bill-pay'].includes(modal?.type)&&e.target.name==='transactionId'){const linked=!!e.target.value;for(const name of ['amount','date']){const input=$('#form [name="'+name+'"]');if(input){input.disabled=linked;input.required=!linked;}}}if(modal?.type==='salary'&&e.target.name==='incomeId'){const t=state.transactions.find(t=>t.id===e.target.value);$('#form [name="amount"]').value=t?(t.amount/100).toFixed(2).replace('.',','):'';$('#form [name="date"]').value=t?.date||(today().startsWith(month)?today():month+'-01');}});
$('#form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{let msg='Modificări salvate.';if(modal.type==='transaction'){const amount=parseMoney(f.get('amount')),name=f.get('name').trim(),date=f.get('date');if(!name)throw Error('Denumirea nu poate fi goală.');if(amount<=0)throw Error('Suma trebuie să fie mai mare decât zero.');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date.slice(0,4)==='0000'||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)throw Error('Alege o dată validă.');const entry={id:modal.id||crypto.randomUUID(),name,amount,date,type:f.get('type'),category:f.get('category'),description:f.get('description').trim(),paymentSource:f.get('paymentSource')||'cash'};mutate(s=>{validateMealPayment(s,entry);const previous=s.transactions.find(t=>t.id===entry.id);preservePlanningLink(previous,entry);if(previous?.salaryMonth){if(entry.type!=='income')throw Error('Salariul asociat bugetului trebuie să rămână un venit.');if(!entry.date.startsWith(previous.salaryMonth+'-'))throw Error('Salariul asociat bugetului trebuie să rămână în aceeași lună.');entry.salaryMonth=previous.salaryMonth;s.budgets[entry.salaryMonth]=entry.amount;}const i=s.transactions.findIndex(t=>t.id===entry.id);if(i<0)s.transactions.push(entry);else s.transactions[i]=entry;if(f.has('saveFavorite')&&!(s.favorites||[]).some(t=>favoriteMatches(t,entry)))toggleFavorite(s,entry);});month=date.slice(0,7);filter={search:'',category:'',type:''};tablePage=1;msg=modal.id?'Tranzacția a fost actualizată.':'Tranzacția a fost adăugată.';}
else if(modal.type==='bill'){const amount=parseMoney(f.get('amount'));mutate(s=>saveBill(s,{id:modal.id,name:f.get('name'),amount,dueDate:f.get('dueDate'),category:f.get('category')}));month=f.get('dueDate').slice(0,7);billDay='';msg='Factura a fost salvată în calendar.';}
else if(modal.type==='bill-pay'){mutate(s=>payBill(s,modal.id,{date:f.get('date'),transactionId:f.get('transactionId')||null}));msg='Factura a fost marcată ca achitată. Plata apare o singură dată în Tranzacții.';}
else if(modal.type==='bill-delete'){mutate(s=>removeBill(s,modal.id));msg='Factura a fost eliminată. Tranzacțiile sunt păstrate.';}
else if(modal.type==='goal'){const targetAmount=parseMoney(f.get('amount'));mutate(s=>saveGoal(s,{id:modal.id,name:f.get('name'),targetAmount,deadline:f.get('deadline'),category:f.get('category')}));msg='Obiectivul a fost salvat.';}
else if(modal.type==='goal-contribute'){const transactionId=f.get('transactionId')||null,amount=transactionId?0:parseMoney(f.get('amount'));mutate(s=>contributeGoal(s,modal.id,{amount,date:f.get('date'),transactionId}));msg='Contribuția a fost adăugată obiectivului.';}
else if(modal.type==='goal-delete'){mutate(s=>removeGoal(s,modal.id));msg='Obiectivul a fost eliminat. Tranzacțiile sunt păstrate.';}
else if(modal.type==='close-month'){mutate(s=>closeMonth(s,month));msg='Rezumatul de închidere a lunii a fost salvat.';}
else if(modal.type==='reopen-month'){mutate(s=>{delete s.monthClosures[month];});msg='Luna a fost redeschisă.';}
else if(modal.type==='copy-budgets'){let copied;mutate(s=>{copied=copyCategoryBudgets(s,month,{replace:f.has('replace')});});msg=copied?`${copied} bugete au fost copiate.`:'Alocările existente au fost păstrate. Nu era nimic de completat.';}
else if(modal.type==='restore'){if(!f.has('confirm')||!pendingRestore)throw Error('Confirmă înlocuirea datelor.');if(!storageFailed)downloadBackup();try{saveState(pendingRestore);}catch{throw Error('Restaurarea nu a putut fi salvată. Datele curente sunt păstrate.');}state=pendingRestore;pendingRestore=null;storageFailed=false;filter={search:'',category:'',type:''};tablePage=1;msg='Backup restaurat. Toate datele au fost salvate în acest browser.';}
else if(modal.type==='salary'){const amount=parseMoney(f.get('amount'));mutate(s=>setMonthlySalary(s,{month,amount,date:f.get('date'),transactionId:f.get('incomeId')||null}));msg='Salariul și bugetul lunar au fost salvate. Îl poți împărți în Categorii.';}
else if(modal.type==='meal'){const amount=parseMoney(f.get('amount'));mutate(s=>setMealVouchers(s,month,amount));msg='Bonurile de masă au fost actualizate.';}
else if(modal.type==='budget'){const amount=parseMoney(f.get('amount'));mutate(s=>s.budgets[month]=amount);msg='Bugetul lunii a fost actualizat.';}
else if(modal.type==='allocation-more'){const amount=parseMoney(f.get('amount'));if(amount<=0)throw Error('Introdu o sumă mai mare decât zero.');mutate(s=>adjustCategoryAllocation(s,month,modal.id,amount));msg='Suma a fost adăugată la buget.';}
else if(modal.type==='category-budget'){const amount=parseMoney(f.get('amount'));mutate(s=>{s.categoryBudgets ??= {};s.categoryBudgets[month] ??= {};if(modal.id==='cat-0'){const mealAmount=parseMoney(f.get('mealAmount'));if(mealAmount>mealSummary(s,month).received)throw Error('Nu poți aloca mai multe bonuri decât ai primit.');s.mealAllocations ??= {};s.mealAllocations[month]=mealAmount;}if(amount)s.categoryBudgets[month][modal.id]=amount;else delete s.categoryBudgets[month][modal.id];});msg='Bugetul categoriei a fost actualizat.';}
else if(modal.type==='category'||modal.type==='subcategory'){
const name=f.get('name').trim();
if(!name)throw Error('Introdu numele categoriei.');
mutate(s=>{
const addingChild=modal.type==='subcategory';
const category=s.categories.find(c=>c.id===modal.id);
if(addingChild&&(!category||category.parentId))throw Error('Alege o categorie principală.');
const parentId=addingChild?category.id:category?.parentId;
if(s.categories.some(c=>c.id!==(addingChild?null:modal.id)&&c.parentId===parentId&&c.name.toLocaleLowerCase('ro-RO')===name.toLocaleLowerCase('ro-RO')))throw Error('Există deja o categorie cu acest nume la acest nivel.');
if(addingChild){
category.isGroup=true;
s.categories.push({id:crypto.randomUUID(),name,parentId,custom:true,color:category.color,icon:'tag'});
}else if(category){category.name=name;category.renamed=true;}
else s.categories.push({id:crypto.randomUUID(),name,custom:true,color:['#818cf8','#38bdf8','#fbbf24','#f472b6'][s.categories.length%4],icon:'tag'});
});
msg=modal.type==='subcategory'?'Subcategoria a fost adăugată.':'Categoria a fost salvată.';
}
else if(modal.type==='delete'){mutate(s=>{const t=s.transactions.find(t=>t.id===modal.id);if(t?.salaryMonth)delete s.budgets[t.salaryMonth];s.transactions=s.transactions.filter(t=>t.id!==modal.id);});msg='Tranzacția a fost ștearsă.';}
else if(modal.type==='delete-category'){mutate(s=>{const cat=s.categories.find(c=>c.id===modal.id);if(!cat)throw Error('Categoria nu mai există.');if(!cat.custom){s.deletedCategoryIds??=[];s.deletedCategoryIds.push(cat.id);}if(cat.id==='cat-0')s.mealAllocations={};s.transactions.forEach(t=>{if(t.category===modal.id)t.category='uncategorized';});s.categories.forEach(c=>{if(c.parentId===modal.id)delete c.parentId;});s.categories=s.categories.filter(c=>c.id!==modal.id);Object.values(s.categoryBudgets||{}).forEach(b=>delete b[modal.id]);});if(filter.category===modal.id)filter.category='';msg='Categoria a fost ștearsă.';}
$('#dialog').close();render();toast(msg);}catch(err){$('#form-error').textContent=err.message;}});
function download(rows){if(!rows.length){toast('Nu există tranzacții de exportat.');return;}const url=URL.createObjectURL(new Blob([csv(rows,state.categories)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`IXpence-${month}-${rows.length}-tranzactii.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportul CSV este pregătit.');}
function toggleTheme(){mutate(s=>s.theme=s.theme==='dark'?'light':'dark');render();}
function action(name){try{if(name==='add-bill')openModal('bill');if(name==='add-goal')openModal('goal');if(name==='close-month')openModal('close-month');if(name==='reopen-month')openModal('reopen-month');if(name==='copy-budgets')openModal('copy-budgets');if(name==='backup')downloadBackup();if(name==='restore'){$('#backup-file').value='';$('#backup-file').click();}if(name==='add')openModal('transaction');if(name==='budget')openModal('budget');if(name==='salary')openModal('salary');if(name==='meal')openModal('meal');if(name==='add-category')openModal('category');if(name==='export')download(filtered());if(name==='export-all')download(state.transactions);if(name==='report-export')download(monthRows());if(name==='theme')toggleTheme();if(name==='reset-filters'){filter={search:'',category:'',type:''};tablePage=1;render();}if(name==='table-prev'){tablePage--;renderTable();}if(name==='table-next'){tablePage++;renderTable();}if(name==='demo'){if(state.transactions.length)return;mutate(s=>{s.transactions=demoTransactions(month).map(t=>s.categories.some(c=>c.id===t.category)?t:{...t,category:'uncategorized'});s.budgets[month]=600000;});render();toast('Date demonstrative adăugate în luna selectată.');}}catch(e){toast(e.message);}}
$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.planningTab){budgetTab=b.dataset.planningTab;billDay='';render();return;}
if(b.dataset.billDay!==undefined){billDay=b.dataset.billDay;render();return;}
for(const [key,type] of [['billEdit','bill'],['billPay','bill-pay'],['billDelete','bill-delete'],['goalEdit','goal'],['goalContribute','goal-contribute'],['goalDelete','goal-delete']])if(b.dataset[key]){openModal(type,b.dataset[key]);return;}
if(b.dataset.favorite){try{const t=state.transactions.find(t=>t.id===b.dataset.favorite);let added;mutate(s=>{added=toggleFavorite(s,t);});render();toast(added?'Tranzacție salvată la favorite.':'Modelul a fost eliminat din favorite.');}catch(e){toast(e.message);}return;}
if(b.dataset.useFavorite){const f=state.favorites?.find(f=>f.id===b.dataset.useFavorite);if(f)openFavorite(f);return;}
if(b.dataset.removeFavorite){try{mutate(s=>s.favorites=s.favorites.filter(f=>f.id!==b.dataset.removeFavorite));render();toast('Favoritul a fost eliminat.');}catch(e){toast(e.message);}return;}
if(b.dataset.allocationStep){try{mutate(s=>adjustCategoryAllocation(s,month,b.dataset.allocationId,Number(b.dataset.allocationStep)*100));render();const next=document.querySelector('[data-allocation-id="'+b.dataset.allocationId+'"][data-allocation-step="'+b.dataset.allocationStep+'"]:not(:disabled)');next?.focus();}catch(e){toast(e.message);}return;}if(b.dataset.allocationMore)openModal('allocation-more',b.dataset.allocationMore);if(b.dataset.resetBudget){try{mutate(s=>resetCategoryBudget(s,month,b.dataset.resetBudget));render();toast('Bugetul alocat a fost resetat la 0. Tranzacțiile sunt păstrate.');}catch(e){toast(e.message);}return;}if(b.dataset.action)action(b.dataset.action);if(b.dataset.edit)openModal('transaction',b.dataset.edit);if(b.dataset.delete)openModal('delete',b.dataset.delete);if(b.dataset.categoryBudget)openModal('category-budget',b.dataset.categoryBudget);if(b.dataset.addChild)openModal('subcategory',b.dataset.addChild);if(b.dataset.editCategory)openModal('category',b.dataset.editCategory);if(b.dataset.deleteCategory)openModal('delete-category',b.dataset.deleteCategory);});
$('#content').addEventListener('input',e=>{if(e.target.id==='search'){filter.search=e.target.value;tablePage=1;renderTable();}});
$('#content').addEventListener('change',e=>{if(e.target.id==='category-filter')filter.category=e.target.value;else if(e.target.id==='type-filter')filter.type=e.target.value;else return;tablePage=1;renderTable();});
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#theme').onclick=()=>action('theme');$('#collapse').onclick=()=>{try{mutate(s=>s.collapsed=!s.collapsed);applyAppearance();icons();}catch(e){toast(e.message);}};
function changeMonth(value){if(!/^\d{4}-\d{2}$/.test(value)||value<'1900-01'||value>'9999-12')return;month=value;billDay='';tablePage=1;render();}
function shiftMonth(delta){const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+delta);changeMonth(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);
function route(){const key=location.hash.slice(1);if(['bills','goals'].includes(key)){page='budgets';budgetTab=key;}else page=pages[key]?key:'dashboard';billDay='';tablePage=1;filter={search:'',category:'',type:''};render();}window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(e.key==='jarvis-expencer-v1'){try{state=loadState();storageFailed=false;render();toast('Datele au fost actualizate din altă filă.');}catch{storageFailed=true;toast('Datele din stocare nu pot fi citite.');}}});
function formatMonth(value){return new Date(value+'-01T12:00:00').toLocaleDateString('ro-RO',{month:'long',year:'numeric'});}
function budgetBadge(allocated,spent){const status=budgetStatus(allocated,spent);return status.label?`<span class="budget-badge ${status.level}">${icon('circle-alert')}${status.label} · ${status.percent}%</span>`:'';}
function budgetAlerts(){const alerts=categoryBudgetSummary(state.transactions,state.categories,state.categoryBudgets,month,mealSummary(state,month).allocated).filter(c=>!c.isGroup&&['warning','full','over'].includes(budgetStatus(c.allocated,c.spent).level));return alerts.length?`<div class="budget-notice" role="status">${icon('circle-alert')}<span><strong>Atenție la bugete:</strong> ${alerts.map(c=>esc(categoryLabel(c,state.categories))+' ('+Math.round(c.used)+'%)').join(', ')}.</span><a href="#categories" class="text-button">Vezi categoriile</a></div>`:'';}
function favoritesView(){const favorites=state.favorites||[];return `<section class="panel favorites-panel"><div class="panel-head"><div><h2>${icon('star')} Tranzacții favorite</h2><p>Alege un model, verifică suma și data, apoi salvează. Steaua din tabel păstrează un model.</p></div></div>${favorites.length?`<div class="favorite-list">${favorites.map(f=>`<div class="favorite-item"><button class="favorite-use" data-use-favorite="${f.id}"><strong>${esc(f.name)}</strong><span>${money(f.amount)} · ${esc(categoryLabel(state.categories.find(c=>c.id===f.category),state.categories))}</span></button><button class="icon-button" data-remove-favorite="${f.id}" aria-label="Elimină favoritul ${esc(f.name)}">${icon('x')}</button></div>`).join('')}</div>`:'<p class="favorites-empty">Nu ai încă favorite. Adaugă o tranzacție și apasă steaua de lângă ea.</p>'}</section>`;}
function openFavorite(f){openModal('transaction');$('#dialog-title').textContent='Adaugă din favorite';for(const key of ['name','description'])$('#form [name="'+key+'"]').value=f[key]||'';$('#form [name="amount"]').value=(f.amount/100).toFixed(2).replace('.',',');$('#form [name="type"][value="'+f.type+'"]').checked=true;$('#form [name="category"]').value=state.categories.some(c=>c.id===f.category)?f.category:'uncategorized';$('#form [name="paymentSource"]').value=f.paymentSource||'cash';}
function comparisonView(){const rows=monthlyComparison(state,month),prev=previousMonth(month),hasPrevious=inMonth(state.transactions,prev).some(t=>t.type==='expense');return `<section class="panel comparison-panel"><div class="panel-head"><div><h2>Față de luna trecută</h2><p>${esc(monthName())} comparativ cu ${esc(formatMonth(prev))} · cheltuieli din bani și bonuri</p></div></div>${!hasPrevious?'<p class="comparison-note">Nu ai cheltuieli înregistrate luna trecută. Valorile din acea lună sunt 0; procentele nu sunt calculate.</p>':''}<div class="table-scroll"><table><thead><tr><th>Categorie</th><th>Luna trecută</th><th>Luna selectată</th><th>Diferență</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${money(r.previous)}</td><td>${money(r.current)}</td><td class="${r.delta>0?'red':r.delta<0?'green':''}">${r.delta>0?'+':r.delta<0?'−':''}${money(Math.abs(r.delta))}${r.percent===null?'':` (${r.percent>0?'+':''}${r.percent.toLocaleString('ro-RO',{maximumFractionDigits:1})}%)`}</td></tr>`).join('')||'<tr><td colspan="4">Nu există cheltuieli de comparat în aceste două luni.</td></tr>'}</tbody></table></div></section>`;}
function downloadFile(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadBackup(){downloadFile(createBackup(state),`IXpence-backup-${today()}-${Date.now()}.json`,'application/json');}
$('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Fișierul este prea mare (maximum 10 MB).');pendingRestore=parseBackup(await file.text());openModal('restore');}catch(err){pendingRestore=null;toast(err.message);}});

function defaultDate(){return today().startsWith(month)?today():month+'-01';}
function shortDate(date){return new Date(date+'T12:00:00').toLocaleDateString('ro-RO');}
function categorySelect(selected){return `<select name="category" required><option value="uncategorized">Fără categorie</option>${state.categories.filter(c=>!c.isGroup).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(categoryLabel(c,state.categories))}</option>`).join('')}</select>`;}
function planningSourceSelect(){const rows=state.transactions.filter(t=>t.type==='expense'&&t.paymentSource!=='meal'&&!t.billId&&!t.goalId&&(!t.savingsContribution||modal?.type==='goal-contribute')).toSorted((a,b)=>b.date.localeCompare(a.date));return `<select name="transactionId"><option value="">Înregistrează o cheltuială nouă</option>${rows.map(t=>`<option value="${t.id}">${esc(t.name)} · ${money(t.amount)} · ${shortDate(t.date)}</option>`).join('')}</select>`;}
function budgetView(){return `<div class="planning-tabs" role="group" aria-label="Secțiuni de buget"><button class="button ${budgetTab==='monthly'?'selected':''}" data-planning-tab="monthly" aria-pressed="${budgetTab==='monthly'}">${icon('wallet')}Buget lunar</button><button class="button ${budgetTab==='bills'?'selected':''}" data-planning-tab="bills" aria-pressed="${budgetTab==='bills'}">${icon('calendar-days')}Calendar de facturi</button><button class="button ${budgetTab==='goals'?'selected':''}" data-planning-tab="goals" aria-pressed="${budgetTab==='goals'}">${icon('target')}Obiective de economisire</button></div>${budgetTab==='bills'?billsView():budgetTab==='goals'?goalsView():monthlyBudgetView()}`;}
function planningOverview(){const bills=(state.bills||[]).filter(b=>b.dueDate.startsWith(month)&&!billPayment(state,b)),overdue=bills.filter(b=>b.dueDate<today()).length;return bills.length?`<div class="budget-notice">${icon('calendar-clock')}<span><strong>${bills.length} facturi de achitat</strong> în luna selectată, în total ${money(bills.reduce((sum,b)=>sum+b.amount,0))}.${overdue?` ${overdue} au scadența depășită.`:''}</span><a href="#bills" class="text-button">Vezi calendarul</a></div>`:'';}
function billsView(){
 const bills=(state.bills||[]).filter(b=>b.dueDate.startsWith(month)).toSorted((a,b)=>a.dueDate.localeCompare(b.dueDate)),visible=billDay?bills.filter(b=>b.dueDate===billDay):bills;
 const first=new Date(month+'-01T12:00:00'),offset=(first.getDay()+6)%7,days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),open=bills.filter(b=>!billPayment(state,b)),paid=bills.length-open.length;
 const names={paid:'Achitată',overdue:'Scadentă depășită',today:'Scadentă azi',upcoming:'De achitat'};
 return `<div class="section-toolbar"><span>Scadențe · ${esc(monthName())}</span><button class="button primary" data-action="add-bill">${icon('plus')}Adaugă factură</button></div><div class="planning-stats"><div class="panel"><span>De achitat</span><strong>${money(open.reduce((sum,b)=>sum+b.amount,0))}</strong></div><div class="panel"><span>Facturi achitate</span><strong>${paid} din ${bills.length}</strong></div><div class="panel"><span>Scadențe depășite</span><strong>${open.filter(b=>b.dueDate<today()).length}</strong></div></div><section class="panel bill-calendar" aria-label="Calendar de facturi"><div class="calendar-caption"><strong>${esc(monthName())}</strong><button class="text-button" data-bill-day="">Toate zilele</button></div><div class="calendar-grid">${['Lu','Ma','Mi','Jo','Vi','Sâ','Du'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${Array.from({length:offset},()=>'<span aria-hidden="true"></span>').join('')}${Array.from({length:days},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0'),rows=bills.filter(b=>b.dueDate===date),unpaid=rows.filter(b=>!billPayment(state,b)),level=unpaid.length?(date<today()?'overdue':'upcoming'):rows.length?'paid':'';return `<button class="calendar-day ${level} ${date===billDay?'selected':''}" data-bill-day="${date}" aria-pressed="${date===billDay}" aria-label="${shortDate(date)} · ${rows.length} facturi"><span>${i+1}</span>${rows.length?`<small>${rows.length} ${rows.length===1?'factură':'facturi'}</small>`:''}</button>`;}).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>${billDay?'Facturi · '+shortDate(billDay):'Facturile lunii'}</h2><p>Planificarea nu scade soldul. Plata este o cheltuială înregistrată o singură dată.</p></div></div><div class="bill-list">${visible.map(b=>{const status=billStatus(state,b,today()),payment=billPayment(state,b);return `<article class="bill-row"><div><h3>${esc(b.name)}</h3><p>Scadență ${shortDate(b.dueDate)} · ${esc(categoryLabel(state.categories.find(c=>c.id===b.category),state.categories))}</p>${payment?`<p>Plătit ${money(payment.amount)} la ${shortDate(payment.date)}. Corecțiile se fac în Tranzacții.</p>`:''}<span class="planning-status ${status}">${names[status]}</span></div><div class="bill-row-actions"><strong>${money(b.amount)}</strong>${payment?'':`<button class="button primary" data-bill-pay="${b.id}">${icon('check')}Achită</button><button class="icon-button" data-bill-edit="${b.id}" aria-label="Editează factura ${esc(b.name)}">${icon('pencil')}</button>`}<button class="icon-button" data-bill-delete="${b.id}" aria-label="Șterge factura ${esc(b.name)}">${icon('trash-2')}</button></div></article>`;}).join('')||'<p class="planning-empty">Nu există facturi pentru această selecție. Adaugă prima factură sau alege altă zi.</p>'}</div></section>`;
}
function goalsView(){return `<div class="section-toolbar"><span>Obiectivele tale · progres cumulat din toate lunile</span><button class="button primary" data-action="add-goal">${icon('plus')}Adaugă obiectiv</button></div><div class="insight">${icon('piggy-bank')}<span>Contribuțiile sunt sume puse deoparte, tratate ca ieșiri din banii disponibili. Poți asocia o cheltuială existentă pentru a evita dublarea. Schimbarea lunii nu resetează progresul.</span></div><section class="goals-grid">${(state.goals||[]).map(g=>{const p=goalProgress(state,g),months={};for(const t of p.rows)months[t.date.slice(0,7)]=(months[t.date.slice(0,7)]||0)+t.amount;return `<article class="panel goal-card"><div class="goal-heading"><div><span class="eyebrow">OBIECTIV DE ECONOMISIRE</span><h2>${esc(g.name)}</h2></div><div><button class="icon-button" data-goal-edit="${g.id}" aria-label="Editează obiectivul ${esc(g.name)}">${icon('pencil')}</button><button class="icon-button" data-goal-delete="${g.id}" aria-label="Șterge obiectivul ${esc(g.name)}">${icon('trash-2')}</button></div></div><div class="goal-amount"><strong>${money(p.saved)}</strong><span>din ${money(g.targetAmount)}</span></div><div class="progress"><span style="width:${Math.min(p.percent,100)}%;${p.percent>=100?'background:var(--green)':''}"></span></div><p>${p.percent>=100?'Obiectiv atins!':`Mai ai ${money(p.remaining)} de pus deoparte.`} · ${Math.round(p.percent)}%</p><p>${esc(categoryLabel(state.categories.find(c=>c.id===g.category),state.categories))}${g.deadline?' · Termen '+shortDate(g.deadline):''}</p><button class="button primary" data-goal-contribute="${g.id}">${icon('plus')}Adaugă contribuție</button><details class="goal-history"><summary>Contribuții pe luni (${p.rows.length} tranzacții)</summary>${Object.keys(months).sort().reverse().map(m=>`<div class="report-stat"><span>${esc(formatMonth(m))}</span><strong>${money(months[m])}</strong></div>`).join('')||'<p>Nu ai încă nicio contribuție.</p>'}</details></article>`;}).join('')||'<div class="panel planning-empty">Adaugă un obiectiv pentru apartament, călătorii sau alt plan. Tu alegi ținta și contribuțiile.</div>'}</section>`;}
function closingTotals(t){return `<dl class="closing-totals"><div><dt>Venituri totale</dt><dd>${money(t.income)}</dd><small>Bani ${money(t.cashIncome)} + bonuri ${money(t.mealIncome)}</small></div><div><dt>Cheltuieli totale</dt><dd>${money(t.expenses)}</dd><small>Din bani ${money(t.cashExpenses)} + bonuri ${money(t.mealExpenses)}</small></div><div><dt>Bani rămași</dt><dd class="${t.cashBalance<0?'red':''}">${money(t.cashBalance)}</dd><small>Venituri în bani minus toate ieșirile din bani</small></div><div><dt>Bonuri rămase</dt><dd>${money(t.mealBalance)}</dd><small>Sold separat de banii disponibili</small></div><div><dt>Pus deoparte pentru economii</dt><dd>${money(t.savings)}</dd><small>Contribuții la obiective și ieșiri în Economii, numărate o singură dată</small></div><div><dt>Tranzacții în lună</dt><dd>${t.transactions}</dd><small>Buget salarial rămas ${money(t.budgetRemaining)}</small></div></dl>`;}
function closingView(){const closure=state.monthClosures?.[month],changed=closureChanged(state,month),totals=closure?.totals||monthlyClosingSummary(state,month);return `<section class="panel closing-panel"><div class="panel-head"><div><h2>${icon('archive')}Închiderea lunii · ${esc(monthName())}</h2><p>${closure?'Rezumat salvat la '+new Date(closure.closedAt).toLocaleString('ro-RO'):'Previzualizare actuală. Salvează un rezumat când vrei să închei luna.'}</p></div><div class="toolbar-buttons"><button class="button primary" data-action="close-month">${icon(closure?'refresh-cw':'check')}${closure?'Recalculează închiderea':'Închide luna'}</button>${closure?'<button class="button" data-action="reopen-month">Redeschide</button>':''}</div></div>${changed?'<div class="closing-changed" role="status">Datele lunii s-au modificat după închidere. Mai jos este rezumatul salvat; recalculează pentru a include valorile noi.</div>':''}${closingTotals(totals)}<p class="closing-note">Economiile puse deoparte sunt deja incluse în cheltuieli; nu se scad încă o dată din sold. Închiderea nu blochează editările și nu reportează automat bani sau bonuri în luna următoare.</p></section>`;}

function dashboardCategoryBars(){
 const categories=mainCategoryBalances(state.transactions,state.categories,state.categoryBudgets,month,mealSummary(state,month).allocated);
 const palette=['#818cf8','#38bdf8','#f59e0b','#f472b6','#34d399','#a78bfa','#fb7185','#22d3ee','#a3e635','#fb923c'];
 return `<section class="panel dashboard-category-bars" aria-label="Solduri pe categorii principale"><div class="category-balance-list">${categories.map((c,i)=>{const color=palette[i]||`hsl(${(i*137.508)%360} 75% 65%)`;return `<div class="category-balance-row" data-category-balance="${c.id}"><div class="category-balance-label"><span><i class="dot" style="background:${color}"></i>${esc(c.name)}</span></div><div class="category-balance-track" role="progressbar" aria-label="Cheltuit · ${esc(c.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(c.percentSpent)}" aria-valuetext="${esc(money(c.spent))} cheltuiți, ${esc(money(c.available))} disponibili din ${esc(money(c.allocated))} alocați${c.available<0?', buget depășit':''}"><span class="category-balance-fill" style="width:${c.percentSpent}%;background:color-mix(in srgb,${color} 65%,#0f1115)"></span><strong class="category-balance-amount">${money(c.available)}</strong><strong class="category-balance-amount on-fill" aria-hidden="true" style="clip-path:inset(0 ${100-c.percentSpent}% 0 0)">${money(c.available)}</strong></div></div>`;}).join('')||'<p class="planning-empty">Nu ai încă nicio categorie. <a class="text-button" href="#categories">Configurează categoriile</a></p>'}</div></section>`;
}

route();if(storageFailed)toast('Stocarea nu poate fi citită. Datele existente nu vor fi suprascrise.');
